// States, one ramp a theme: a cell's state from the background (dead, never walked; under: Ocean's sea) through the dying
// grey-blue to the ink (alive), f from 0 to 1: a Life cell's dying stages, an ant's states alike
const stateColour = (f, under = UNLIT) => rampAt([under, PALETTE.dying, LIFE_ALIVE], f);
const statesPicture = () => swatch([0.25, 0.5, 0.75, 1].map((f) => stateColour(f))); // (States' tile, Life's and an ant's)
// Trail: a Life cell just dead, fading over 8 gens to the empty cell's colour (UNLIT), pale from its first one: a
// warm echo, read as dead at once (till v0.4.1038 from a near black, a dead cell as dark as a live one for 3 gens:
// at 72 gens a second, steps of grey all over a soup), not a state
const TRAIL_INK = {
  light: ['#b9ae98', '#e7e0d0'],
  dark: ['#636b7c', '#3a4150'],
};
let PALETTE, MONO, UNLIT, OCEAN, LANDS, LIFE_ALIVE, EDGE_RGB, EDGE_ALPHA, SHADE, FADE_EDGES, TILE_LIFT; // TILE_LIFT: the tiles' rainbow mixed with white  // EDGE_RGB, EDGE_ALPHA: the tile edges; SHADE: how dark a tile turned away gets
function setPalette(theme) {
  const P = PALETTES[theme];
  // the surfaces' tile edges light on a dark page, dark on a light one, as the 2D grid
  UNLIT = P.unlit;
  OCEAN = P.ocean;
  LANDS = P.lands;
  LIFE_ALIVE = P.alive;
  EDGE_RGB = P.edgeRgb;
  EDGE_ALPHA = P.edgeAlpha;
  SHADE = P.shade;
  FADE_EDGES = !!P.fadeEdges;
  TILE_LIFT = P.tileLift ?? 0;
  PALETTE = P;
  LIFE_TRAIL.splice(0, 8, ...Array.from({ length: 8 }, (_, i) => rampAt([...TRAIL_INK[theme], UNLIT], i / 8)));
  LIFE_HUES.forEach((h, k) => {
    LIFE_COLOURS[k] = `hsl(${h}, 85%, ${PALETTES.light.light}%)`;
  }); // the light page's, on a dark one too (to compare)
  DIGIT_COLORS.splice(0, DIGIT_COLORS.length, ...P.digits);
  Object.assign(DIRECTION_COLOURS, P.directions);
  GREY = P.grey;
  MONO = P.mono;
}
// the page's theme (light or dark) and the app's rainbow at f, from 0 to 1 (its GRADIENT, BANDS colours); its colour of hue h
const themeName = () => (document.documentElement.dataset.theme === 'light' ? 'light' : 'dark');
const gradientAt = (f) => rainbowNow()[Math.round(f * (BANDS - 1))];
function rainbowHue(h) {
  return `hsl(${h}, 85%, ${PALETTE.light}%)`;
}
// the app's own rainbow at f, 0 to 1, Ocean or not: from its blue, 190, round by red, 360, to orange (the icons' always)
const appRainbowAt = (f) => rainbowHue(190 + 200 * f);
// Earth's (Ocean's switch): its six lands in a rainbow's order, green, lime, yellow, ochre, a glacier's cyan, ice white, a
// theme's (see PALETTES: their order there a Sextet's teams', the near ones apart)
const earthColours = (P = PALETTE) => [P.lands[0], P.lands[3], P.lands[2], P.lands[5], P.lands[4], P.lands[1]];
// the rainbow now, GRADIENT filled again in place whenever the theme or Ocean changed (gradientKey: what it was made for):
// the app's (appRainbowAt); on Ocean, Earth's colours (earthColours)
let gradientKey = null;
function rainbowNow() {
  const ocean = oceanOn(),
    key = `${themeName()}|${ocean}`;
  if (key === gradientKey) return GRADIENT;
  gradientKey = key;
  for (let i = 0; i < BANDS; i++)
    GRADIENT[i] = ocean ? rampAt(earthColours(), i / (BANDS - 1)) : appRainbowAt(i / (BANDS - 1));
  return GRADIENT;
}
setPalette(themeName());

