const icon = (name) => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${ICONS[name]}</svg>`;
// the plane's outline: its shape and its edges, one choice (see outlineOf): a rectangle, a torus or walled; a six-fold grid
// walled in a hexagon round its middle (see planeShape); a slanted one's rhombus of cells as stored, a torus or walled.
// Its picture doubled with bricks: walled (the cells past its edges always dead); else a torus (its edges glued: what leaves on one side comes back
// on the other)
const OUTLINES = [
  ['square', true, 'Square', 'A rectangle, a torus'],
  ['square', false, 'Walls', 'A rectangle, its cells past its edges always dead'],
  ['hex', false, 'Hex', 'A hexagon round its middle, walled: its cells past its edges always dead'],
  ['rhombus', true, 'Rhombus', 'The grid as it is stored, its cells a slanted block, a torus'],
  [
    'rhombus',
    false,
    'R. walls',
    'The grid as it is stored, its cells a slanted block, those past its edges always dead',
  ],
];
$('planeEdges').append(
  iconTabs(
    OUTLINES.map(([shape, torus, text, title]) =>
      tile({
        pic: icon({ square: 'square', hex: 'hexagon', rhombus: 'rhombus' }[shape] + (torus ? '' : 'Walled')),
        text,
        id: `outline-${shape}-${torus ? 'torus' : 'walled'}`,
        byDefault: text === 'Square' ? 'yes' : '',
        title,
        click: () => {
          plane.shape = shape;
          plane.torus = torus;
          if (torus) spaceTime = false;
          compute();
        },
      }),
    ),
  ),
); // (Stacks off on a torus)
// Stacks (Space-time, in 3D: walls with it, left on when it goes off; a torus, Stacks off too), on squares: under Square boxes
const spaceTimeTile = tile({
  pic: icon('stacks'),
  text: 'Stacks',
  toggle: true,
  byDefault: 'off',
  title:
    "The generations stacked up, in 3D, time going up, a cube a live cell, as many gens as asked under the play buttons (a glider: a slanting line; an oscillator: a column); turned as a 3D walk. With walls: through a torus's edges no tree grows",
  click: () => {
    spaceTime = !spaceTime;
    if (spaceTime) plane.torus = false;
    $('perspective').checked = perspectiveFor(tabVariant(), 0, spaceTimeOn());
    compute();
  },
});
// an element's HTML with links in it, written again only when it changes: against what was written, not its HTML now (a link
// hovered has its title turned into data-tip, see the tooltips: rewritten each frame, the link under the mouse replaced, its click
// lost), and not while one of its links is pressed (Play: its text changes each frame, the click between two)
const setLinks = (el, html) => {
  if (el.dataset.html !== html && !el.querySelector(':active')) {
    el.innerHTML = html;
    el.dataset.html = html;
  }
};
// A text that may hold 🎲, 🐉 or ▮ (a random number, the dragon, the prime barcode), as HTML with their icons, each keeping
// its character beside it, read but not drawn (.visually-hidden): a text read from it again (a saved name, a tooltip's, a
// copy) the same text
const SYMBOL_ICONS = { '🎲': 'dice', '🐉': 'dragon', '▮': 'barcode' };
const withIcons = (text) =>
  text.replace(/🎲|🐉|▮/gu, (c) => `${icon(SYMBOL_ICONS[c])}<span class="visually-hidden">${c}</span>`);

/* ==============================================================================================
 * PART 4 — NUMBER FORMULAS
 * ==============================================================================================
 *
 * Every number is a formula: pi, sqrt(2), (1+sqrt(5))/2, 2^pi, ln(3), zeta(5), 22/7, 2^127-1,
 * primorial(392113)+1, randprime(300,81244), random(81244), champernowne… The Number cards only
 * write formulas, and a setup stores the formula: one uniform way to store every number.
 *
 * Why a language of our own rather than math.js or another library: they compute with floating
 * point (about 16 digits) or with a fixed-precision decimal type, while we need up to a million
 * exact digits in any base, computed in a worker with the algorithms of Part 1. So only the
 * syntax is borrowed (the usual calculator one: + − * / ^, sqrt(…), ln(…)); the parser, the
 * checks and the evaluation are ours, a few hundred lines, with no dependency.
 *
 * Canonical form: what is stored is the formula as written, tidied up — no spaces, lower case,
 * π → pi, × → *, only the parentheses needed. So "PI", " π " and a click on the π card all store
 * "pi". It is deliberately not algebra: pi*pi stays pi*pi and does not become pi^2. Simplifying
 * would need a computer algebra system and would rewrite the user's formula under their eyes; two
 * writings of one value just give two links, with the same digits.
 *
 * Kinds, set on every node by checkFormula:
 *   'int'   an exact integer             2^127-1, primorial(11)+1, sqrt(16)
 *   'rat'   an exact fraction            22/7, 2^-1, (16/81)^(3/4)
 *   'real'  computed with guard digits   pi, sqrt(2), 2^pi, ln(3)
 *   'seq'   a sequence of digits defined base by base (random, champernowne, copelanderdos, primebarcode, primegaps,
 *           and the 0s and 1s of dragon, thuemorse, rabbit, liouville, kempner, moserdebruijn).
 *           It is not a number, so it only stands alone: random(5)+1 is refused.
 * The kind decides where digits come from: sequences on the page (seqDigits), everything else in
 * the worker. An exact number, an integer or a fraction, has digits after the point as a real does: 0s once it ends.
 */

/* ---- 4.1 Vocabulary ----------------------------------------------------------------------- */
const FORMULA_NAMES = {
  // name: [kind, symbol shown, patterned: its digits a pattern by their definition (automatic, morphic), see patternAreaCap]
  pi: ['real', 'π'],
  e: ['real', 'e'],
  phi: ['real', 'φ'],
  gamma: ['real', 'γ'],
  catalan: ['real', 'G'],
  erdos: ['real', 'E'],
  rho: ['real', 'ρ'],
  champernowne: ['seq', 'C'],
  primebarcode: ['seq', '▮ p'],
  primegaps: ['seq', 'gₙ'],
  dragon: ['seq', '🐉', true],
  thuemorse: ['seq', 'τ', true],
  rabbit: ['seq', 'F', true],
  rudinshapiro: ['seq', 'RS', true],
  kolakoski: ['seq', 'K'], // (Kolakoski: no pattern proved)
  liouville: ['seq', 'L'],
  copelanderdos: ['seq', 'CE'],
  kempner: ['seq', 'κ', true],
  moserdebruijn: ['seq', 'MB', true],
};
const FORMULA_FUNCTIONS = {
  sqrt: 1,
  cbrt: 1,
  root: 2,
  ln: 1,
  exp: 1,
  log: 2,
  zeta: 1,
  primorial: 1,
  random: 1,
  randprime: 2,
};
const APPROX = {
  pi: Math.PI,
  e: Math.E,
  phi: (1 + Math.sqrt(5)) / 2,
  gamma: 0.5772156649,
  catalan: 0.9159655942,
  erdos: 1.6066951524,
  rho: 0.4146825099,
};
const PREC = { '+': 1, '-': 1, '*': 2, '/': 2, neg: 3, '^': 4 }; // anything else binds tighter (5)
const precOf = (x) => PREC[x.k] ?? 5;
const formulaKids = (x) => (x.k === 'call' ? x.args : x.k === 'neg' ? [x.a] : x.a ? [x.a, x.b] : []);
const formulaNodes = (x) => [x, ...formulaKids(x).flatMap(formulaNodes)];

/* ---- 4.2 Parser --------------------------------------------------------------------------- */
// A small recursive-descent parser, one function per precedence level (expr → term → unary →
// power → primary). Unicode input is turned into plain names first, so the rest only sees ASCII.
// Text → tree of { k: 'num' | 'name' | 'call' | 'neg' | '+' | '-' | '*' | '/' | '^', … }.
// Accepts π φ γ ρ √ ∛ − × · ÷, any case, and implicit products like 2pi.
function parseFormula(text) {
  const src = text
    .replace(/π/g, ' pi ')
    .replace(/φ/g, ' phi ')
    .replace(/γ/g, ' gamma ')
    .replace(/ρ/g, ' rho ')
    .replace(/[−–]/g, '-')
    .replace(/[×·]/g, '*')
    .replace(/÷/g, '/');
  const tokens = [],
    re = /(\d+(?:\.\d+)?)|([a-z_][a-z0-9_]*)|([-+*/^(),√∛])/iy;
  for (let pos = 0; pos < src.length;) {
    if (/\s/.test(src[pos])) {
      pos++;
      continue;
    }
    re.lastIndex = pos;
    const m = re.exec(src);
    if (!m) throw new Error(`unexpected “${src[pos]}”`);
    pos = re.lastIndex;
    if (m[1]) {
      // number without useless zeros: 007 → 7, 1.50 → 1.5
      const [i, f = ''] = m[1].split('.'),
        int = i.replace(/^0+(?=\d)/, ''),
        frac = f.replace(/0+$/, '');
      tokens.push({ t: 'num', v: frac ? `${int}.${frac}` : int });
    } else tokens.push(m[2] ? { t: 'id', v: m[2].toLowerCase() } : { t: m[3] });
  }
  let i = 0;
  const peek = () => tokens[i]?.t;
  const expect = (t) => {
    if (peek() !== t) throw new Error(`“${t}” expected`);
    i++;
  };
  const expr = () => {
    let a = term();
    while (peek() === '+' || peek() === '-') a = { k: tokens[i++].t, a, b: term() };
    return a;
  };
  const term = () => {
    let a = unary();
    for (;;) {
      if (peek() === '*' || peek() === '/') a = { k: tokens[i++].t, a, b: unary() };
      else if (['num', 'id', '(', '√', '∛'].includes(peek()))
        a = { k: '*', a, b: power() }; // 2pi
      else return a;
    }
  };
  const unary = () => {
    if (peek() === '-') {
      i++;
      return { k: 'neg', a: unary() };
    }
    if (peek() === '+') {
      i++;
      return unary();
    }
    return power();
  };
  const power = () => {
    const a = primary();
    if (peek() !== '^') return a;
    i++;
    return { k: '^', a, b: unary() }; // right to left: 2^3^2 = 2^(3^2)
  };
  const primary = () => {
    const x = tokens[i++];
    if (!x) throw new Error('the formula is incomplete');
    if (x.t === 'num') return { k: 'num', v: x.v };
    if (x.t === '(') {
      const a = expr();
      expect(')');
      return a;
    }
    if (x.t === '√' || x.t === '∛') return { k: 'call', f: x.t === '√' ? 'sqrt' : 'cbrt', args: [power()] };
    if (x.t === 'id' && FORMULA_FUNCTIONS[x.v] !== undefined) {
      const args = [];
      if (peek() === '(') {
        // random and randprime(300) may leave out their seed
        i++;
        if (peek() !== ')') {
          args.push(expr());
          while (peek() === ',') {
            i++;
            args.push(expr());
          }
        }
        expect(')');
      }
      return { k: 'call', f: x.v, args };
    }
    if (x.t === 'id' && FORMULA_NAMES[x.v]) return { k: 'name', v: x.v };
    if (x.t === 'id') throw new Error(`unknown name “${x.v}”`);
    throw new Error(`unexpected “${x.t}”`);
  };
  if (!tokens.length) throw new Error('empty');
  const ast = expr();
  if (i < tokens.length) throw new Error(`unexpected “${tokens[i].v ?? tokens[i].t}”`);
  return ast;
}

/* ---- 4.3 Printing: the canonical text and the symbol shown -------------------------------- */
// The canonical text: no spaces, lower case, explicit *, only the parentheses needed
function canonical(x) {
  const wrap = (y, need) => (need ? `(${canonical(y)})` : canonical(y));
  switch (x.k) {
    case 'num':
    case 'name':
      return x.v;
    case 'call':
      return `${x.f}(${x.args.map(canonical).join(',')})`;
    case 'neg':
      return `-${wrap(x.a, precOf(x.a) <= 3)}`; // -(a+b), -(-a)
    case '^':
      return `${wrap(x.a, precOf(x.a) <= 4)}^${wrap(x.b, precOf(x.b) < 3)}`;
    default:
      return `${wrap(x.a, precOf(x.a) < PREC[x.k])}${x.k}${wrap(x.b, precOf(x.b) <= PREC[x.k])}`;
  }
}

// The symbol shown in the title and the status: π², √2, e^π, 392,113# + 1, 🎲…
const superscript = (v) => String(v).replace(/\d/g, (c) => '⁰¹²³⁴⁵⁶⁷⁸⁹'[c]);
function pretty(x) {
  const wrap = (y, need) => (need ? `(${pretty(y)})` : pretty(y));
  const arg = (y) => wrap(y, y.k !== 'num' && y.k !== 'name');
  switch (x.k) {
    case 'num':
      return x.v;
    case 'name':
      return FORMULA_NAMES[x.v][1];
    case 'neg':
      return `−${wrap(x.a, precOf(x.a) <= 3)}`;
    case '^':
      return x.b.k === 'num' && !x.b.v.includes('.') && x.b.v.length <= 3
        ? `${wrap(x.a, precOf(x.a) <= 4)}${superscript(x.b.v)}`
        : `${wrap(x.a, precOf(x.a) <= 4)}^${wrap(x.b, precOf(x.b) < 3)}`;
    case 'call': {
      const [a, b] = x.args;
      return {
        sqrt: () => `√${arg(a)}`,
        cbrt: () => `∛${arg(a)}`,
        root: () => `${superscript(b.v)}√${arg(a)}`,
        ln: () => (a.k === 'num' || a.k === 'name' ? `ln ${pretty(a)}` : `ln(${pretty(a)})`),
        exp: () => `exp(${pretty(a)})`,
        zeta: () => `ζ(${pretty(a)})`,
        log: () =>
          b.k === 'num' && !b.v.includes('.') ? `log${subscript(b.v)} ${arg(a)}` : `log(${pretty(a)}, ${pretty(b)})`,
        primorial: () => `${formatNumber(Number(a.v))}#`,
        random: () => '🎲',
        randprime: () => `🎲 p${subscript(a.v)}`,
      }[x.f]();
    }
    default: {
      const op = { '+': ' + ', '-': ' − ', '*': '×', '/': '/' }[x.k]; // (×, not ·: · parts a bubble's words)
      return `${wrap(x.a, precOf(x.a) < PREC[x.k])}${op}${wrap(x.b, precOf(x.b) <= PREC[x.k])}`;
    }
  }
}

/* ---- 4.4 Checking: sizes, small exact values and kinds ------------------------------------ */
// Sizes are estimated as log10, which never overflows even for 2^136279841-1 or exp(10^9): they
// give the guard digits, and refuse what is too large before any work starts.
// ≈ log10 of the value of a checked node, never overflowing (sizes and guard digits)
function formulaLog10(x) {
  const L = formulaLog10,
    a = x.args?.[0];
  switch (x.k) {
    case 'num': {
      const f = Math.log10(Number(x.v));
      return Number.isFinite(f) ? f : f > 0 ? x.v.split('.')[0].length - 1 : 0;
    }
    case 'name':
      return x.kind === 'seq' ? 0 : Math.log10(APPROX[x.v]);
    case 'neg':
      return L(x.a);
    case '+':
    case '-':
      return Math.max(L(x.a), L(x.b)) + 0.302;
    case '*':
      return L(x.a) + L(x.b);
    case '/':
      return L(x.a) - L(x.b);
    case '^': {
      // a^b: b·log10 a, with b ≈ ±10^L(b) when it is not a whole number
      if (x.exp !== undefined) return x.exp * L(x.a);
      return Math.min(1e9, 10 ** Math.min(9, L(x.b))) * Math.abs(L(x.a));
    }
    default:
      return {
        sqrt: () => L(a) / 2,
        cbrt: () => L(a) / 3,
        root: () => L(a) / Number(x.args[1].v),
        ln: () => Math.log10(Math.max(Math.abs(L(a)) * Math.LN10, 0.01)),
        log: () => 0,
        exp: () => Math.min(1e9, 10 ** Math.min(9, L(a))) / Math.LN10,
        zeta: () => 0.2,
        primorial: () => Number(a.v) / Math.LN10,
        randprime: () => Number(a.v) - 1,
        random: () => 0,
      }[x.f]();
  }
}

// Exact value of a small exact node, else null (while checking: perfect powers, exponents)
function smallExact(x) {
  if (x.kind !== 'int' && x.kind !== 'rat') return null;
  if (formulaNodes(x).some((y) => y.k === 'call') || Math.abs(formulaLog10(x)) > 1000) return null;
  try {
    return exactValue(x, () => {
      throw new Error('not small');
    });
  } catch {
    return null;
  }
}

// Checks a parsed formula, fills in the random seeds left out, and sets node.kind (and for powers
// node.exp, node.eBase or node.rootExp). Throws an Error with a readable message.
function checkFormula(root) {
  const noSeq = (x) => {
    if (x.kind === 'seq') throw new Error(`${canonical(x)} is a sequence of digits, not a number: use it alone`);
  };
  const whole = (x, lo, hi, what) => {
    if (x.k !== 'num' || x.v.includes('.') || Number(x.v) < lo || Number(x.v) > hi) {
      throw new Error(`${what} must be a whole number from ${formatNumber(lo)} to ${formatNumber(hi)}`);
    }
    return Number(x.v);
  };
  const visit = (x) => {
    if (x.k === 'call') {
      if (x.f === 'random' && !x.args.length) x.args.push({ k: 'num', v: String(freshDraw()) });
      if (x.f === 'randprime' && x.args.length === 1) x.args.push({ k: 'num', v: String(freshDraw()) });
      const arity = FORMULA_FUNCTIONS[x.f];
      if (x.args.length !== arity) throw new Error(`${x.f}(…) takes ${arity} value${arity > 1 ? 's' : ''}`);
    }
    formulaKids(x).forEach(visit);
    switch (x.k) {
      case 'num':
        x.kind = x.v.includes('.') ? 'rat' : 'int';
        break;
      case 'name':
        x.kind = FORMULA_NAMES[x.v][0];
        break;
      case 'neg':
        noSeq(x.a);
        x.kind = x.a.kind;
        break;
      case '+':
      case '-':
      case '*':
        noSeq(x.a);
        noSeq(x.b);
        x.kind =
          x.a.kind === 'real' || x.b.kind === 'real'
            ? 'real'
            : x.a.kind === 'int' && x.b.kind === 'int'
              ? 'int'
              : 'rat';
        break;
      case '/':
        noSeq(x.a);
        noSeq(x.b);
        if (smallExact(x.b)?.[0] === 0n) throw new Error('division by zero'); // (by an exact 0, whatever it divides: refused as read)
        if (x.a.kind === 'real' || x.b.kind === 'real') x.kind = 'real';
        else {
          x.kind = 'rat';
          const v = smallExact(x);
          if (v && v[1] === 1n) x.kind = 'int';
        }
        break;
      case '^': {
        noSeq(x.a);
        noSeq(x.b);
        const k = x.b.kind === 'int' ? smallExact(x.b) : null;
        if (k && k[0] <= 1_000_000_000n && k[0] >= -1_000_000_000n) {
          // a whole power: exact when a is (its size is checked by readFormula)
          x.exp = Number(k[0]);
          x.kind = x.a.kind === 'real' ? 'real' : x.exp < 0 ? 'rat' : x.a.kind;
          break;
        }
        // any other power: e^y, a^(p/q) with a small q (a root, exact when a^p is a perfect q-th power),
        // else e^(y·ln a)
        x.kind = 'real';
        if (x.a.k === 'name' && x.a.v === 'e') {
          x.eBase = true;
          break;
        }
        const r = x.b.kind === 'rat' ? smallExact(x.b) : null;
        if (r && r[1] <= 64n && r[0] <= 1000n && r[0] >= -1000n) {
          x.rootExp = [Number(r[0]), Number(r[1])];
          const v = smallExact(x.a);
          if (v && v[0] >= 0n) {
            const [e, q] = x.rootExp,
              K = BigInt(q),
              up = e >= 0 ? [v[0] ** BigInt(e), v[1] ** BigInt(e)] : [v[1] ** BigInt(-e), v[0] ** BigInt(-e)];
            if (up[1] !== 0n && iroot(up[0], q) ** K === up[0] && iroot(up[1], q) ** K === up[1])
              x.kind = x.a.kind === 'int' && e >= 0 ? 'int' : 'rat';
          }
        }
        break;
      }
      case 'call':
        switch (x.f) {
          case 'random':
            whole(x.args[0], 0, 4294967295, 'The seed of random(…)');
            x.kind = 'seq';
            break;
          case 'randprime':
            whole(x.args[0], 10, 5000, 'The size of randprime(size, seed)');
            whole(x.args[1], 0, 4294967295, 'The seed of randprime(size, seed)');
            x.kind = 'int';
            break;
          case 'primorial':
            whole(x.args[0], 2, 20_000_000, 'p in primorial(p)');
            x.kind = 'int';
            break;
          case 'ln':
          case 'exp':
            noSeq(x.args[0]);
            x.kind = 'real';
            break;
          case 'log':
            noSeq(x.args[0]);
            noSeq(x.args[1]);
            x.kind = 'real';
            break;
          case 'zeta':
            whole(x.args[0], 2, 100, 'k in zeta(k)');
            x.kind = 'real';
            break;
          default: {
            // sqrt, cbrt, root: exact when the value is a perfect power
            noSeq(x.args[0]);
            const k = x.f === 'sqrt' ? 2 : x.f === 'cbrt' ? 3 : whole(x.args[1], 2, 64, 'The degree k in root(x, k)');
            const v = smallExact(x.args[0]),
              K = BigInt(k);
            const perfect = v && v[0] >= 0n && iroot(v[0], k) ** K === v[0] && iroot(v[1], k) ** K === v[1];
            x.kind = perfect ? x.args[0].kind : 'real';
          }
        }
    }
  };
  visit(root);
}

/* ---- 4.5 Reading the Formula field -------------------------------------------------------- */
// The formula of the Formula field, checked and written back in canonical form
let formulaInUse = '1/112'; // the last formula that was valid, for the link and the Gallery
// The number in use till one is picked: π on a walk, 1/112 elsewhere (a Life start's digits, an ant's turns: a highway for
// the square ant). One picked, typed or linked other than its variant's own is kept from variant to variant
const defaultNumber = (w) => (NAV[w]?.[0] === 'Walk' ? 'pi' : '1/112');
let numberPicked = false;
const pickNumber = (text, w) => {
  numberPicked = text !== defaultNumber(w);
};
function readFormula() {
  const F = formulaOf($('formula').value);
  if (!F.error) $('formula').value = formulaInUse = F.text;
  return F;
}
// a formula's text read and checked: its tree, canonical text, symbol, kind and size; or its error
function formulaOf(typed) {
  try {
    const ast = parseFormula(typed);
    checkFormula(ast);
    const text = canonical(ast),
      nodes = formulaNodes(ast);
    const mag = Math.max(...nodes.map((x) => Math.abs(formulaLog10(x))));
    if (ast.kind === 'int' && formulaLog10(ast) > 45e6)
      throw new Error('too large: more than 45 million decimal digits');
    if (ast.kind === 'real' && mag > 1e5) throw new Error('too large or too small for a computation with guard digits');
    const m = text.match(/^2\^(\d+)-1$/); // a Mersenne prime shows as M₁₂₇
    const sym = m && MERSENNE.includes(Number(m[1])) ? `M${subscript(m[1])}` : pretty(ast);
    const root = ast.k === 'name' ? ast.v : ast.k === 'call' ? ast.f : null;
    return { ast, text, sym, root, kind: ast.kind, mag, nodes: nodes.length, log10: formulaLog10(ast) };
  } catch (err) {
    return { error: err.message };
  }
}

/* ---- 4.6 Number cards: from a formula to its card and back -------------------------------- */
// The card a formula comes from, with the value of its helper menu; none for a formula of its own
// a page of another site, in a new tab: its words in the links' colour (the one link of its kind, see .external-link)
const externalLink = (url, words) =>
  `<a class="external-link" href="${url}" target="_blank" rel="noopener">${htmlText(words)}</a>`;
// a fraction p/q, as written; the name a number goes by: a fraction, itself; else its card's (see PRESETS); '' for a
// formula of one's own
const isFraction = (formula) => /^\d+\/\d+$/.test(formula);
const numberName = (formula) => (isFraction(formula) ? formula : (PRESETS[presetOf(formula).id]?.name ?? ''));
// a number's Wikipedia page (see PRESETS' wiki), as a link in its name; '' when it has none
const wikiLink = (formula) => {
  const p = PRESETS[presetOf(formula).id];
  return p?.wiki ? externalLink(`https://en.wikipedia.org/wiki/${p.wiki}`, numberName(formula)) : '';
};
function presetOf(text) {
  const found = Object.keys(PRESETS).find((id) => PRESETS[id].f === text);
  if (found) return { id: found };
  let m;
  if ((m = text.match(/^2\^(\d+)-1$/)) && MERSENNE.includes(Number(m[1]))) return { id: 'mersenne', mersenneP: m[1] };
  if (
    (m = text.match(/^primorial\((\d+)\)([+-])1$/)) &&
    (m[2] === '+' ? PRIMORIAL_PLUS : PRIMORIAL_MINUS).includes(Number(m[1]))
  ) {
    return { id: 'primorial', primorialP: `${m[1]},${m[2] === '+' ? 1 : -1}` };
  }
  if (/^random\(\d+\)$/.test(text)) return { id: 'random' };
  if (/^randprime\(\d+,\d+\)$/.test(text)) return { id: 'randomPrime' };
  return { id: null }; // a formula of its own: no card
}

// The cards and their helper menus follow the formula
function syncNumberMenu() {
  const p = presetOf($('formula').value);
  renderNumberPicker(p.id);
  $('formula').classList.toggle('custom', !p.id || !!PRESETS[p.id].draw); // a formula of its own, typed or drawn, lights up like a chosen card
  for (const helper of ['mersenneP', 'primorialP']) if (p[helper]) $(helper).value = p[helper];
  $('mersenneRow').hidden = p.id !== 'mersenne';
  $('primorialRow').hidden = p.id !== 'primorial';
}

// The numbers by tabs (one group of tabs: ℚ the fractions, ℝ the constants and sequences, ℙ 🎲 the draws and primes), a
// tab's groups shown, each a grid of tiles showing the symbol, several per row, the name and the formula on hover, a card
// clicked again its page (Full number). The tab shown: the number's own, till another is picked (a picked number: its own
// again). The helper menus of the primes (which Mersenne, which primorial, what size) sit right under their group (every
// group made, those of other tabs hidden: the menus kept in the page)
const NUMBER_TABS = [
  [
    'ℚ',
    ['Fractions'],
    'Fractions, their digits coming back round a loop (the rosettes found on the turtles), to edit in Formula',
  ],
  [
    'ℝ',
    ['Constants', 'Sequences'],
    'Famous constants (π, e, φ, √2, ln 2, ζ(3), the prime constant…) and sequences laid as digits (Thue–Morse, Champernowne, prime gaps)',
  ],
  [
    'ℙ 🎲',
    ['Random and primes'],
    'Digits or a prime drawn at random (a link giving the same draw again), Mersenne and primorial primes',
  ],
]; // (name, its groups, its tooltip)
// the tab shown (the first at the start), changed by a click on a tab, or by another number shown (numberShown) with a card:
// its card's tab (a formula of its own: no card to show elsewhere, the tab kept)
let numberTab = NUMBER_TABS[0][0],
  numberShown = null;
// the tab of a card (see presetOf: a formula found among the cards); none for a formula of its own
const numberTabOf = (active) => NUMBER_TABS.find(([, groups]) => groups.includes(PRESETS[active]?.group))?.[0];
// a card's symbol: a fraction its numerator over its denominator (see .fraction), as in maths
const cardSymbol = (sym) => {
  const m = sym.match(/^(\d+)\/(\d+)$/);
  return m ? `<span class="fraction"><span>${m[1]}</span><span>${m[2]}</span></span>` : withIcons(sym);
};
// the cards of a tab's groups
const cardsIn = (groups) => Object.keys(PRESETS).filter((id) => groups.includes(PRESETS[id].group));
// the Fractions' cards in order: by their digits in base 10 (p's and q's: 4/3 two, 22/7 three, 355/113 six), fewer first,
// then by value
const fractionOrder = (a, b) => {
  const [p, q] = PRESETS[a].f.split('/'),
    [r, s] = PRESETS[b].f.split('/');
  return p.length + q.length - r.length - s.length || p / q - r / s;
};
function renderNumberPicker(active) {
  if (active !== numberShown) {
    numberShown = active;
    numberTab = numberTabOf(active) ?? numberTab;
  }
  const shown = NUMBER_TABS.find(([name]) => name === numberTab)[1];
  const tabs = textTabs(
    NUMBER_TABS.map(([name, , title]) => {
      const b = document.createElement('button');
      b.type = 'button';
      b.title = title;
      b.innerHTML = withIcons(name);
      b.classList.toggle('active', name === numberTab);
      b.addEventListener('click', () => {
        numberTab = name;
        renderNumberPicker(active);
      }); // (its cards shown, the number kept: only a card or a draw changes it)
      return b;
    }),
  );
  $('numberTabs').replaceChildren(tabs);
  // A number card's tooltip (its menu's too): its symbol a picture, its name in bold over its words; a fraction's, the
  // fraction itself, its name in its words; then the formula it writes (one built from its menu or drawn, once picked)
  const numberTip = (el, id) => {
    const p = PRESETS[id],
      formula = id === active ? formulaInUse : typeof p.f === 'string' ? p.f : '',
      fraction = isFraction(formula);
    el.setAttribute('aria-label', fraction ? formula : p.name);
    el.title = (fraction ? [p.name, p.detail] : [p.detail]).filter(Boolean).join(', ');
    el.dataset.formula = fraction ? '' : formula;
  };
  $('numberList').replaceChildren(
    ...NUMBER_GROUPS.map((group) => {
      const box = document.createElement('div'),
        grid = document.createElement('div');
      box.hidden = !shown.includes(group);
      grid.className = 'number-grid';
      grid.setAttribute('role', 'listbox');
      const ids = group === 'Fractions' ? cardsIn([group]).sort(fractionOrder) : cardsIn([group]); // (the others as written)
      const pick = (id) => {
        numberShown = id;
        pickPreset(id);
      }; // (its tab kept)
      grid.append(
        ...ids.map((id) => {
          const p = PRESETS[id],
            b = document.createElement('button');
          b.innerHTML = cardSymbol(p.sym);
          numberTip(b, id);
          b.setAttribute('role', 'option');
          setTile(b, { on: id === active, again: true }); // (clicked again: its page, see toggleNumber)
          b.addEventListener('click', () => (id === active ? toggleNumber() : pick(id)));
          return b;
        }),
      );
      // a drawn card's (draw: Random digits, Random prime) wide button under its group: the card picked's, none of the group
      // picked the first's (Random digits); another draw at each click
      const drawn = ids.includes(active) ? [active] : ids;
      const draws = drawn
        .filter((id) => PRESETS[id].draw)
        .slice(0, 1)
        .map((id) => {
          const b = document.createElement('button');
          b.className = 'wide';
          b.innerHTML = `${icon('dice')} ${PRESETS[id].name}`;
          b.title = 'Another draw'; // (an action: the card picked shows lit, never this button)
          b.addEventListener('click', () => pick(id));
          return b;
        });
      box.append(grid, ...draws);
      if (group === 'Random and primes') {
        numberTip($('mersenneRow'), 'mersenne'); // (a prime's menu: its card's tooltip)
        numberTip($('primorialRow'), 'primorial');
        box.append($('mersenneRow'), $('primorialRow'));
      }
      return box;
    }),
  );
}

/* ---- 4.7 Sequences and digit helpers ------------------------------------------------------ */
// the whole number k's digits in base b, its first first, written into digits from i on (as many as fit): the place after
// them (as numbers: x.toString(b) writes 10 as a, read back as 49 in base 11 and over)
function wholeDigitsInto(digits, i, k, b) {
  const ds = [];
  for (; k > 0; k = Math.floor(k / b)) ds.push(k % b);
  for (let c = ds.length - 1; c >= 0 && i < digits.length; c--) digits[i++] = ds[c];
  return i;
}
// Digits of a sequence (kind 'seq'), computed on the main thread
function seqDigits(ast, n, base) {
  const digits = new Uint8Array(n),
    name = ast.k === 'call' ? ast.f : ast.v;
  if (name === 'random') {
    // reproducible: the same seed always gives the same digits
    const rng = seededRandom(Number(ast.args[0].v));
    const lim = 2 ** 32 - (2 ** 32 % base); // rejection sampling for a uniform distribution
    for (let i = 0; i < n; i++) {
      let r;
      do r = rng();
      while (r >= lim);
      digits[i] = r % base;
    }
  } else if (name === 'champernowne') {
    // 0.1 2 3 … written in base b one after another
    for (let i = 0, k = 1; i < n; k++) i = wholeDigitsInto(digits, i, k, base);
  } else if (name === 'primebarcode') {
    // digit k (k = 1, 2, …) is 0 if k is not prime, else k mod b; a prime equal to b counts as 1.
    // In base 2 this is exactly the binary expansion of the prime constant ρ = Σ 2^(−p)
    const composite = sieve(n);
    for (let k = 2; k <= n; k++) if (!composite[k]) digits[k - 1] = k % base || 1;
  } else if (name === 'dragon') {
    // regular paperfolding sequence: fold n (n = 1, 2, …) is 0 when n / 2^k (odd) ≡ 1 mod 4, else 1.
    // Read as turns (left / right) it is the dragon curve; its digits are 0 and 1 in every base.
    for (let i = 0; i < n; i++) {
      let k = i + 1;
      while (k % 2 === 0) k /= 2;
      digits[i] = k % 4 === 1 ? 0 : 1;
    }
  } else if (name === 'thuemorse') {
    // digit k: the parity of the 1s of k in base 2; 0 and 1 in every base
    for (let i = 1; i < n; i++) digits[i] = digits[i >> 1] ^ (i & 1);
  } else if (name === 'rabbit') {
    // the Fibonacci word: from 1, each 1 becomes 10 and each 0 becomes 1
    digits[0] = 1;
    for (let i = 0, j = 0; j < n; i++) {
      if (digits[i]) {
        digits[j++] = 1;
        if (j < n) digits[j++] = 0;
      } else digits[j++] = 1;
    }
  } else if (name === 'rudinshapiro') {
    // the blocks 11 of k (k & k >> 1: their last 1s), counted mod 2
    for (let i = 0; i < n; i++) {
      let m = i & (i >> 1),
        p = 0;
      while (m) {
        p ^= 1;
        m &= m - 1;
      }
      digits[i] = p;
    }
  } else if (name === 'liouville') {
    // digit k is 1 when k is a factorial (1, 2, 6, 24…): 0 and 1 in every base
    for (let f = 1, m = 1; f <= n; f *= ++m) digits[f - 1] = 1;
  } else if (name === 'kempner') {
    // digit k is 1 when k is a power of 2 (1, 2, 4, 8…): 0 and 1 in every base
    for (let k = 1; k <= n; k *= 2) digits[k - 1] = 1;
  } else if (name === 'moserdebruijn') {
    // digit k is 1 when k has only 0s and 1s in base 4 (1, 4, 5, 16…: sums of distinct powers of 4): 0 and 1 in every base
    for (let i = 0; i < n; i++) {
      let k = i + 1;
      while (k && k % 4 < 2) k = Math.floor(k / 4);
      digits[i] = k ? 0 : 1;
    }
  } else if (name === 'copelanderdos') {
    // 2 3 5 7 11 … written in base b one after another: the primes up to x give about x / ln b digits (sieved again,
    // twice as far, in the rare case they fall short)
    for (let limit = Math.ceil(n * Math.log(base)) + 100, i = 0; i < n; limit *= 2) {
      const composite = sieve(limit);
      i = 0;
      for (let k = 2; k <= limit && i < n; k++) if (!composite[k]) i = wholeDigitsInto(digits, i, k, base);
    }
  } else if (name === 'kolakoski') {
    // 1 2 2 1 1 2 …: run i is as long as term i, its terms 1 and 2 by turns
    const k = [1, 2, 2];
    for (let i = 2; k.length < n; i++) for (let r = 0; r < k[i] && k.length < n; r++) k.push(1 + (i % 2 === 0 ? 0 : 1));
    for (let i = 0; i < n; i++) digits[i] = k[i] - 1;
  } else {
    // primegaps
    // gaps between consecutive odd primes (3→5, 5→7, 7→11, …) are even: digit = (gap / 2) mod b.
    // The n-th prime is below n·(ln n + ln ln n) for n ≥ 6.
    const limit = Math.ceil((n + 2) * (Math.log(n + 2) + Math.log(Math.log(n + 2)))) + 100;
    const composite = sieve(limit);
    let prev = 3;
    for (let k = 5, i = 0; i < n; k += 2) {
      if (composite[k]) continue;
      digits[i++] = ((k - prev) / 2) % base;
      prev = k;
    }
  }
  return { intPart: '0', digits };
}

// Digits of a non-negative integer (Number or BigInt) in base b, one character per digit
// with character code 48 + digit ('0'–'9' in base ≤ 10). BigInt.toString stops at base 36,
// so base 64 is read from the binary expansion, 6 bits per digit.
function digitString(x, base) {
  if (base !== 64) return x.toString(base);
  const bits = x.toString(2);
  const pad = bits.padStart(Math.ceil(bits.length / 6) * 6, '0');
  let out = '';
  for (let i = 0; i < pad.length; i += 6) out += String.fromCharCode(48 + parseInt(pad.slice(i, i + 6), 2));
  return out;
}

// Sieve of Eratosthenes: composite[k] = 1 for every composite k ≤ limit (and for 0 and 1)
function sieve(limit) {
  const composite = new Uint8Array(limit + 1);
  composite[0] = composite[1] = 1;
  for (let i = 2; i * i <= limit; i++) {
    if (composite[i]) continue;
    for (let j = i * i; j <= limit; j += i) composite[j] = 1;
  }
  return composite;
}

// kind: the formula's ('int', 'rat' for a fraction, 'real' or 'seq'); ratio: an exact number's [p, q] (BigInt), an
// integer's [N, 1]
function setCurrent(entry, base, kind, ratio = null) {
  digitsComputed = {
    head: headDigits(entry.intPart, base),
    digits: entry.digits,
    base,
    variant: tabVariant(),
    formula: formulaInUse,
    ratio, // its digits end up repeating, an integer's 0s too (see torusLoops)
    patterned: kind === 'int' || kind === 'rat' || !!FORMULA_NAMES[formulaInUse]?.[2],
  }; // its digits a pattern: a fraction's period, a dragon's folds (see patternAreaCap)
}
// an integer part's digits (its text, without its leading zeros), one a byte
function headDigits(intPart, base) {
  const t = intPart.replace(/^0+/, ''),
    head = new Uint8Array(t.length);
  for (let i = 0; i < t.length; i++) {
    const c = t.charCodeAt(i);
    head[i] = base < 64 && c >= 97 ? c - 87 : c - 48;
  } // past base 10: a, b, c…
  return head;
}

// A number's first n digits in base b, its integer part first, as one array (F: formulaOf's): a sequence's made on the
// page, the others' from the cache (A's, see compute); null when they are not there yet (see digitsWorker)
function knownDigits(F, base, n) {
  if (F.kind === 'seq') return seqDigits(F.ast, n, base).digits;
  const hit = digitsCache[digitsKey(F, base)];
  if (!hit || hit.intPart.length + hit.digits.length < n) return null;
  const head = headDigits(hit.intPart, base),
    all = new Uint8Array(head.length + hit.digits.length);
  all.set(head);
  all.set(hit.digits, head.length);
  return all.subarray(0, n);
}
// a worker computing them, cached when done (then: called with its error, if any; share: with its share done, as it goes);
// it, to be stopped
function digitsWorker(F, base, n, then, share = () => {}) {
  const w = newFormulaWorker();
  w.onmessage = ({ data: d }) => {
    if (d.type === 'progress') return share(d.p);
    w.terminate();
    if (d.type !== 'error')
      digitsCache[digitsKey(F, base)] = {
        intPart: d.intPart,
        digits: d.digits,
        tests: d.tests,
        uncertain: d.uncertain,
      };
    then(d.type === 'error' ? d.message : null);
  };
  w.postMessage({ ast: F.ast, n, base, mag: F.mag, nodes: F.nodes });
  return w;
}
// Digits B to L, a battle's other numbers (see battleOn): their formulas (RIVALS: their fields, made by formulaField) read as the Digits'
// (formulaOf), as many digits as A's in the same base, for the walkers but A (walkTeams − 1). Null while a worker computes
// some (then: called once they are all there), { error } for a wrong formula
const RIVALS = [...'BCDEFGHIJKL'].map((c) => `formula${c}`),
  rivalWorkers = {};
const formulaName = (id) => (id === 'formula' ? 'Formula' : `Formula ${id.slice(-1)}`); // (A's Formula, then Formula B, Formula C…)
// B's, C's… numbers at first
const RIVAL_FIRSTS = [
  'e',
  'phi',
  'sqrt(2)',
  'sqrt(3)',
  'sqrt(5)',
  'ln(2)',
  'zeta(3)',
  'sqrt(7)',
  'cbrt(2)',
  'gamma',
  'catalan',
];
// a walker's formula field, the same for every walker (A's the Digits' own, then B's, C's… in a battle's Walkers, see
// renderWalkTeams): its number at first, its words, ↵; A's Show digits in it (see showDigitsTip)
const FORMULA_WORDS =
  "Typed in base 10, then written in the base its use needs (the walk's, or Life's: K + 1, its colours and dead), as the chip beside it says. Any number as a formula: pi, e, phi, gamma, catalan, erdos, rho, sqrt(3), cbrt(2), root(x, k), ln(x), exp(x), log(x, b), zeta(k), 22/7, 2^pi, 8^(1/3), 2^127-1, primorial(p)+1, randprime(size, seed), and + − × ÷ ^ ( ). Digit sequences, used alone: random(seed), champernowne, copelanderdos, primebarcode, primegaps, liouville, kempner, moserdebruijn, dragon. Press Enter to compute";
function formulaField(id, first) {
  const box = document.createElement('div');
  box.className = 'field formula-field';
  box.innerHTML =
    `<input id="${id}" type="text" value="${first}" spellcheck="false" autocomplete="off" aria-label="${formulaName(id)}" title="${FORMULA_WORDS}">` +
    '<button class="enter" type="button" tabindex="-1" title="Compute (Enter)">↵</button>' +
    (id === 'formula' ? '<button id="copyNumber" type="button" hidden></button>' : '');
  return box;
}
$('numberTabs').after(formulaField('formula', '1/112'));
$('rivalFormulas').append(...RIVALS.map((id, j) => formulaField(id, RIVAL_FIRSTS[j])));
// the walkers' first numbers: A's the Digits' own on a walk, then B's, C's… (RIVAL_FIRSTS), as many as walkers
const battleFirsts = () => [defaultNumber(tabVariant()), ...RIVAL_FIRSTS.slice(0, walkTeams - 1)];
function rivalsDigits(base, n, then) {
  const out = [];
  for (const id of RIVALS.slice(0, walkTeams - 1)) {
    const F = formulaOf($(id).value);
    if (F.error) return { error: `${formulaName(id)}: ${F.error}` };
    const known = knownDigits(F, base, n);
    if (known) {
      out.push(known);
      continue;
    }
    rivalWorkers[id]?.terminate();
    waitBegin(id, `Computing ${formulaName(id)}, ${F.sym ?? ''} in base ${base}`);
    rivalWorkers[id] = digitsWorker(
      F,
      base,
      n,
      (error) => {
        delete rivalWorkers[id];
        waitEnd(id);
        if (error) $('status').textContent = `${formulaName(id)}: ${error}`;
        else if (!Object.keys(rivalWorkers).length) then();
      },
      (p) => waitShare(id, p),
    );
  }
  return Object.keys(rivalWorkers).length ? null : out;
}
// whether a battle's other numbers' digits are all there (or wrong: the walk built says it), before its walk is built:
// else then() once they are, the walk built only then (A's alone shown meanwhile, whole, was a flash of another walk)
const rivalsReady = (then) => !battleOn() || rivalsDigits(VARIANTS[tabVariant()].base, digitsNeeded(), then) !== null;
const stopRivals = () => {
  for (const id of Object.keys(rivalWorkers)) {
    rivalWorkers[id].terminate();
    delete rivalWorkers[id];
    waitEnd(id);
  }
};

// The digits in use: n in total, the integer part (always included) then the digits after the point
function digitsInUse() {
  const n = digitsNeeded();
  const head = digitsComputed.head.subarray(0, n);
  return { head, frac: digitsComputed.digits.subarray(0, n - head.length) };
}
// The digits just after those walked (as many as are known, up to LOOP_AHEAD): a walk compares
// them to tell a loop (see buildEdgesWalk)
const LOOP_AHEAD = 64;
function digitsAhead() {
  const n = digitsNeeded(),
    H = digitsComputed.head,
    D = digitsComputed.digits,
    out = [];
  for (let i = n; i < n + LOOP_AHEAD; i++) {
    const d = i < H.length ? H[i] : D[i - H.length];
    if (d === undefined) break;
    out.push(d);
  }
  return Uint8Array.from(out);
}

// Digits ds in base b written: the first head (its integer part), then a point and the rest (a 0 before it implicit: .001).
// Up to base 36 one character per digit (0–9, then a–z); above that each digit as a decimal number, space-separated
const writeDigits = (ds, b, head) => {
  const write = (x) => (b <= 36 ? Array.from(x, (v) => v.toString(36)).join('') : Array.from(x).join(' '));
  return ds.length > head ? `${write(ds.subarray(0, head))}.${write(ds.subarray(head))}` : head ? write(ds) : '0';
};
// the formulas shown (see showNumber): the Digits' one (its digits', never a formula read since), or a battle's, each walker's
const numberFormulas = () => [
  digitsComputed.formula,
  ...RIVALS.slice(0, walk.battle?.player ? walk.battle.player.K - 1 : 0).map((id) => $(id).value),
];
// how many digits of them in base b: those in use, or in another base as many as they tell
const numberLength = (b) => {
  const { head, frac } = digitsInUse(),
    n = head.length + frac.length;
  return b === digitsComputed.base ? n : Math.floor((n * Math.log(digitsComputed.base)) / Math.log(b));
};
// the numbers shown in base b: each its digits (n of them), its integer part's (head) and the rest (frac), an exact
// number's value (ratio, its period shown), its formula (its Wikipedia link, see wikiLink); in another base than the walk's (Base 10), computed from its formula as the walk's are: null while some are
// not (see numberDigitsIn)
function numberRows(b = digitsComputed.base) {
  const own = b === digitsComputed.base,
    { head, frac } = digitsInUse(),
    n = numberLength(b);
  const rows = numberFormulas().map((f, s) => {
    const F = formulaOf(f),
      ds = !s && own ? Uint8Array.from([...head, ...frac]) : knownDigits(F, b, n);
    if (!ds) return null;
    const lead =
        !s && own
          ? digitsComputed.head.length
          : F.kind === 'seq'
            ? ds.length
            : headDigits(digitsCache[digitsKey(F, b)].intPart, b).length,
      h = Math.min(lead, n); // (its integer part's digits)
    return {
      s,
      name: s ? (F.text ?? f) : f,
      formula: f,
      n,
      head: ds.subarray(0, h),
      frac: ds.subarray(h, n),
      ratio: s ? smallExact(F.ast) : digitsComputed.ratio,
    };
  });
  return rows.includes(null) ? null : rows;
}
// the numbers shown computed in base b from their formulas, as the walk's are (a fraction's digits exact: 3/4 = .75000…);
// the page shown again once they are all there
function numberDigitsIn(b) {
  if (waits.has('numberBase')) return;
  const n = numberLength(b),
    missing = numberFormulas()
      .map(formulaOf)
      .filter((F) => !knownDigits(F, b, n));
  let left = missing.length;
  waitBegin('numberBase', `Computing the digits in base ${b}`);
  for (const F of missing)
    digitsWorker(F, b, n, (error) => {
      if (error) base10.on = false;
      if (--left) return;
      waitEnd('numberBase');
      if (!$('numberPreview').hidden) showNumber();
    });
}

/* ==============================================================================================
 * PART 5 — PICKING A MODE, COMPUTING, BUILDING THE WALK
 * ==============================================================================================
 *
 * compute() is the one entry point: any change (number, variant, surface, rule, digits) calls it. It
 * reads the formula, shows the controls the variant needs, takes the digits from the cache or from
 * the worker, then builds the whole walk (buildWalk) and shows it complete.
 */

/* ---- 5.1 Walk variant picker ----------------------------------------------------------------- */
// The categories of the (hidden) variant menu as tabs, and every choice of the selected tab as a
// list. Picking a choice sets the menu and fires its change event, so the rest of the page only
