  R2: { short: 'sharp right', text: 'turns right by two notches (120° on hexagons), then a step' },
  U: { short: 'U-turn', text: 'leaves by the edge it came in by' },
  B: { short: 'back', text: 'a step back, still facing the same way' },
  '^': { short: 'up', text: 'turns up, then a step (cubes)' },
  v: { short: 'down', text: 'turns down, then a step (cubes)' },
  p: { short: 'turn up', text: 'turns up on the spot, no step (cubes)' },
  u: { short: 'up', text: 'a step up, whatever its heading (cubes)' },
  d: { short: 'down', text: 'a step down, whatever its heading (cubes)' },
