  const faces = hullFacesOf(kind),
    squareFaces = faces.filter((fc) => fc.corners.length === 4),
    triFaces = faces.filter((fc) => fc.corners.length === 3);
  const { verts, add } = vertexStore(),
    tiles = [],
    downs = [], // (a triangle's way in its face's grid, see flatPolyhedron)
    at = (A, B, C, i, j) => add(...facePoint(A, B, C, i / f, j / f));
  for (const {
    corners: [A, B, , D],
  } of squareFaces)
    for (let i = 0; i < f; i++)
      for (let j = 0; j < f; j++)
        tiles.push([at(A, B, D, i, j), at(A, B, D, i + 1, j), at(A, B, D, i + 1, j + 1), at(A, B, D, i, j + 1)]);
