    start: (i) => walkStart(g, variant, i + 1),
    step,
    key: ([t, entry, p, q, hand = 1]) => (((t * k + entry) * k + ((p + k) % k)) * 2 + q) * 2 + (hand < 0 ? 1 : 0), // (its hand: a Klein bottle's, see surfaceStep)
