    const rows = table.split('\n'),
      n = Number(rows.find((line) => line.startsWith('n_states:'))?.slice(9) ?? 0),
      k = rows.includes('neighborhood:Moore') ? 8 : 4,
      turns = !rows.includes('symmetries:none');
