// with a tie for the most (the one missing born, see lifeStep): each at least one, the e = c − (K − 1) left over not 1 (2 of 3
// colours: e even); with letters, any of theirs with c (rule: a setup's, the field's by default)
const colourMissing = (K, rule = lifeRuleAsked()) => {
  const r = parseRule(ruleBody(rule));
  if (K < 3 || !r) return false;
  return countsOn(r, r.B).some((c) => c >= K - 1 && (K === 3 ? (c - 2) % 2 === 0 : c - (K - 1) !== 1));
};
// a choice among a few (Start's DUEL_CUTS, PIECES and START_PLACES: [words, title] each, see PART_CHOICES), its tabs: the
// one picked (now) on, its first the default, each its choice's key (field:k, see choicesAt), all greyed where whyNot(setup)
// says why; a click on another picks it (pick), then plays the game again (then)
const choiceTile = (field, [text, title], k, now, pick, whyNot, then = compute) =>
  tile({
    text,
    title,
    on: now === k,
    byDefault: k ? '' : 'yes',
    choice: `${field}:${k}`,
    whyNot: whyNot && ((s) => whyNot(s, k)), // (each tab its own: a start's place's three, see PART_CHOICES)
    click: () => {
      if (now !== k) {
        pick(k);
        then();
      }
    },
  });
const choiceTabs = (field, list, now, pick, whyNot, then) =>
  textTabs(list.map((item, k) => choiceTile(field, item, k, now, pick, whyNot, then)));
// Teams, Life's and a walk's alike (its own: see walkTeamTiles)
function renderTeams() {
  const w = tabVariant();
  debugTuning(); // (the debug panel's Solo or battle)
  const zones = lifeTeams > 1 && walk.life && walk.variant === w ? zoneShapeOf(lifeTeams) : null, // (the walk shown's, built)
    cut = PART_CHOICES.torusCut,
    cutNow = cut.now(),
    cuts = TORUS_CUTS.map(([key]) => key);
  $('teamsZones').replaceChildren(
    ...(!VARIANTS[w].life
      ? []
      : [
          textTabs(
            ZONE_SHAPES.map(([key, text, title]) =>
              cutNow >= 0 && cuts.includes(key)
                ? choiceTile('torusCut', [text, title], cuts.indexOf(key), cutNow, cut.pick, cut.whyNot) // (a torus of the plane's: its cut picked)
                : tile({
                    text,
                    title,
                    on: key === zones,
                    can: key === zones,
                    greyed: zones ? 'Not how this figure lays its teams.' : 'Solo: one team, no zones.',
                  }),
            ),
          ),
        ]),
  ); // (Life's only; shown only, out of the menu's graph: a torus of the plane's cut a choice, see TORUS_CUTS)
  if (walkTeamsHere(w)) {
    $('colourBlocks').replaceChildren(...walkTeamTiles());
    return;
  }
  $('colourBlocks').replaceChildren(
    ...TEAM_COUNTS.map((k) =>
      tile({
        pic: teamBlock(k),
        text: TEAM_NAMES[k],
        title: `${k === 1 ? 'One colour: alive or dead' : `${k} teams: ${LIFE_COLOUR_NAMES.slice(0, k).join(', ')}`}${colourMissing(k) ? ' · a colour gone can come back: a tie, the missing one born' : ''}`,
        on: k === lifeTeams,
        choice: `lifeTeams:${k}`, // (out of the menu's graph, see OFF_GRAPH)
        whyNot: ({ w, size, rule }) => lifeTeamsWhyNot(k, w, size, rule),
        mark: colourMissing(k),
        byDefault: k === 1 ? 'yes' : '',
        click: () => {
          if (k !== lifeTeams) {
            lifeTeams = k;
            compute();
          }
        },
      }),
    ),
    // Mixed, a switch: the colours' cells mixed at random in one place, as one colour's (greyed in one colour and where no zone mixes, see mixable)
    tile({
      pic: `<svg viewBox="0 0 4 4" aria-hidden="true">${[
        [0, 0],
        [2, 0],
        [1, 1],
        [3, 1],
        [0, 2],
        [2, 2],
        [1, 3],
        [3, 3],
      ]
        .map(
          ([x, y], i) =>
            `<rect x="${x}" y="${y}" width="1" height="1" fill="${LIFE_COLOURS[[0, 4, 2, 6, 5, 1, 7, 3][i]]}"/>`,
        )
        .join('')}</svg>`,
      text: 'Mixed',
      title: 'The teams placed as one is (one patch, a soup), each cell a team at random',
      toggle: true,
      byDefault: 'off',
      on: teamsMixed(),
      whyNot: ({ w, lifeTeams: teams = lifeTeams, start = plane.start, zone = hunt.zone }) =>
        teams > 1 && mixable(zone, VARIANTS[w], start) ? '' : MIXED_WHERE,
      click: () => {
        teamsMix = !teamsMix;
        compute();
      },
    }),
    // Newcomer, a switch (see newcomerCan)
    tile({
      pic: teamBlock(Math.max(3, lifeTeams), true),
      text: 'Newcomer',
      toggle: true,
      byDefault: 'off',
      choice: 'newcomer',
      on: newcomerOn(),
      click: () => {
        newcomer = !newcomer;
        compute();
      },
      whyNot: ({ w, size, lifeTeams: teams = lifeTeams, start = plane.start, rule = lifeRuleAsked() }) =>
        newcomerCan(teams, w, size, start, rule) ? '' : newcomerWhere(teams),
      title:
        lifeTeams > 2
          ? `${TEAM_NAMES[lifeTeams - 1] ?? `${lifeTeams - 1} teams`} as it starts, and ${teamName(lifeTeams - 1)} a newcomer: none at first, born of a tie between the others (the colour missing)`
          : "The teams below's start, and the last colour a newcomer: none at first, born of a tie between the others (the colour missing)",
    }),
  );
}
// a walk's teams: Solo, Duel, Trio… as Life's (a battle: how many numbers walk; greyed, a count its surface's symmetries
// cannot set apart from its start at this size, see battleCounts)
function walkTeamTiles() {
  const words = (k) =>
    k === 1
      ? 'One number walks'
      : k === 2
        ? "Two numbers walk, A's and B's, from opposite places (how they fight: below)"
        : `${k} numbers walk, A's to ${'ABCDEFGHIJKL'[k - 1]}'s, from A's place moved by ${k} of the surface's symmetries: each walks as A would from there (how they fight: below)`;
  return TEAM_COUNTS.map((k) =>
    tile({
      pic: teamBlock(k),
      text: TEAM_NAMES[k],
      title: words(k),
      on: k === (battleOn() ? walkTeams : 1),
      byDefault: k === 1 ? 'yes' : '',
      choice: `teams:${k}`, // (out of the menu's graph, see OFF_GRAPH)
      whyNot: ({ w: v, size, startNo: j }) => teamsWhyNot(k, v, size, j),
      click: () => {
        if (k !== walkTeams) {
          walkTeams = k;
          compute();
        }
      },
    }),
  ); // (its choice's key, see choicesAt)
}
