      `<text x="${m[0]}" y="${m[1]}" font-size="${S * 0.3}" font-weight="600" fill="${t === c ? '#fff' : 'var(--text-color)'}" text-anchor="middle" dominant-baseline="central">${count(t)}</text></svg>`
