    grid = bounds?.match(/^[TKP](\d+)\*?,(\d+)/i), // (Golly's bounded grid, a torus, a Klein bottle or a plane: its width and height)
    pos = lines.find((line) => line.startsWith('#CXRLE'))?.match(/Pos=(-?\d+),(-?\d+)/),
